// Compute the determinant of the 3x3 matrix
double det = m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
           - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
           + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);

// Check if the matrix is invertible (determinant != 0)
if (std::abs(det) < 1e-10) {
    // Return identity matrix as fallback (or could throw an exception)
    return mat3{};
}

// Compute the inverse using the adjugate matrix divided by the determinant
mat3 inverse;
inverse[0][0] =  (m[1][1] * m[2][2] - m[1][2] * m[2][1]) / det;
inverse[0][1] = -(m[0][1] * m[2][2] - m[0][2] * m[2][1]) / det;
inverse[0][2] =  (m[0][1] * m[1][2] - m[0][2] * m[1][1]) / det;

inverse[1][0] = -(m[1][0] * m[2][2] - m[1][2] * m[2][0]) / det;
inverse[1][1] =  (m[0][0] * m[2][2] - m[0][2] * m[2][0]) / det;
inverse[1][2] = -(m[0][0] * m[1][2] - m[0][2] * m[1][0]) / det;

inverse[2][0] =  (m[1][0] * m[2][1] - m[1][1] * m[2][0]) / det;
inverse[2][1] = -(m[0][0] * m[2][1] - m[0][1] * m[2][0]) / det;
inverse[2][2] =  (m[0][0] * m[1][1] - m[0][1] * m[1][0]) / det;

return inverse;

